// A soft light follows the pointer only on fine-pointer devices with motion enabled.
(()=>{const fine=matchMedia('(hover:hover) and (pointer:fine)'),reduce=matchMedia('(prefers-reduced-motion:reduce)');let active=null,frame=0,last=null;const glow=document.createElement('div');glow.className='pointer-glow';glow.setAttribute('aria-hidden','true');document.body.append(glow);const clear=()=>{active?.classList.remove('pointer-lit');active=null;glow.classList.remove('visible')};function draw(){frame=0;if(!last||!fine.matches||reduce.matches||!siteContent.motion||location.pathname==='/manage'){clear();return}const {x,y,target}=last;glow.style.transform=`translate3d(${x-220}px,${y-220}px,0)`;glow.classList.add('visible');const next=target.closest('.category,.project-copy,.hero-copy,.about-grid>div');if(next!==active){active?.classList.remove('pointer-lit');active=next}if(active){const rect=active.getBoundingClientRect();active.style.setProperty('--pointer-x',(x-rect.left)+'px');active.style.setProperty('--pointer-y',(y-rect.top)+'px');active.classList.add('pointer-lit')}}document.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;last={x:e.clientX,y:e.clientY,target:e.target};if(!frame)frame=requestAnimationFrame(draw)},{passive:true});document.addEventListener('pointerout',e=>{if(!e.relatedTarget){last=null;clear()}});window.addEventListener('blur',clear);window.addEventListener('scroll',()=>{last=null;clear()},{passive:true});window.addEventListener('hashchange',clear);fine.addEventListener('change',clear);reduce.addEventListener('change',clear);})();
